using System;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.AI;using Mirror;using MultiFPS;using MultiFPS.Gameplay;using MultiFPS.Gameplay.RiftEnemies;using ROM.Horde;using ROM.UI.Gameplay;using ROM.UI.Sprint01;
namespace ROM.EditorTools {public static partial class RiftJournalProbe {
 static System.Collections.Generic.List<RiftEnemyAgent> animals=new System.Collections.Generic.List<RiftEnemyAgent>();static RiftEnemyDefinition[] bestiary;static int beastIndex,beastBefore;static RiftEnemyAgent beast;static RiftFieldUI field;
 public static void RunBestiary(){Run();SessionState.SetBool(Key+"Bestiary",true);SessionState.SetBool(Key+"UI",true);SessionState.SetString(Key+"Bindings",PlayerPrefs.GetString(RiftControls.Preference,""));}
 static void BestiaryTick(CharacterInstance actor,PlayerInstance player,RiftGameplayHUD hud,RiftMMOController input){var world=ROM.Horde.Horde.Instance;
 if(step==600){var population=UnityEngine.Object.FindFirstObjectByType<RiftEnemyPopulation>();population.enabled=false;world.enabled=false;foreach(var enemy in RiftEnemyAgent.All.ToArray())enemy.Despawn();Check(population.Zones.Count(z=>!z.Encounter)==7,"Seven wildlife zones in existing islands");Check(population.Zones.Where(z=>z.Encounter).All(z=>z.Encounter.NativeSpawn),"Every encounter uses independent prefab spawning");Check(population.Zones.Where(z=>z.Encounter&&z.Encounter.MiniBoss).All(z=>z.Count==1&&z.Enemies[0].Enemy.IsBoss),"Single native regent in each miniboss zone");bestiary=AssetDatabase.FindAssets("t:RiftEnemyDefinition",new[]{"Assets/ROM/Enemies/Bestiary"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<RiftEnemyDefinition>).ToArray();Check(bestiary.Length==12,"Five infernal enemies and seven animal species");foreach(var d in bestiary){Check(d.Prefab&&NetworkManager.singleton.spawnPrefabs.Contains(d.Prefab.gameObject),"Registered own network prefab: "+d.DisplayName);Check(d.Prefab.Animator.avatar.isValid&&d.Prefab.Animator.runtimeAnimatorController.animationClips.Length==8,"Own native animation set: "+d.DisplayName);Check(!d.Prefab.GetComponent<CharacterInstance>()&&!d.Prefab.GetComponent<BotAI>(),"Independent AI: "+d.DisplayName);Check(d.Prefab.GetComponentsInChildren<Renderer>().All(r=>r.sharedMaterials.All(m=>m&&m.shader.isSupported&&m.GetTexture("_BaseMap"))),"Supported textured materials: "+d.DisplayName);if(!d.IsWildlife)Check(d.Prefab.GetComponentsInChildren<MeshRenderer>().Length>0,"Included weapon remains attached: "+d.DisplayName);}field=UnityEngine.Object.FindFirstObjectByType<RiftFieldUI>();Check(field&&field.Potions.Length==2,"Editable field UI and compact potion slots in scene");Press(UnityEngine.InputSystem.Key.M);Advance(.5);return;}
 if(step==601){Capture("world-map");Check(field.MapOpen&&field.MapImage.texture,"M opens baked full-world map");Check(!UICursorManager.GamePlayInput(),"Open map captures gameplay cursor");field.SetZoom(9);Check(field.Content.localScale.x==4,"Map zoom is bounded");Check(field.Content.GetComponentsInChildren<UnityEngine.UI.Button>().Length>=world.Checkpoints.Length,"World map exposes crystal and encounter pins");Press();Advance(.2);return;}
 if(step==602){Press(UnityEngine.InputSystem.Key.M);Advance(.4);return;}
 if(step==603){Check(!field.MapOpen,"M closes full map");Press();var village=player.GetComponent<RiftVillagePlayer>();PlayerPrefs.SetInt(RiftVillageSupplies.Key(0),3);PlayerPrefs.SetInt(RiftVillageSupplies.Key(1),3);actor.Health.ServerSetVitals(100,10);village.PotionReadyAt=0;Check(village.ServerDrinkPotion(0,out _),"Normal potion heals from its selected slot");Check(actor.Health.CurrentHealth>=50&&RiftVillageSupplies.Count(0)==2&&RiftVillageSupplies.Count(1)==3,"40% heal consumes only normal potion: HP="+actor.Health.CurrentHealth+" max="+actor.Health.MaxHealth+" count0="+RiftVillageSupplies.Count(0)+" count1="+RiftVillageSupplies.Count(1));Check(!village.ServerDrinkPotion(1,out _),"Potion types share authoritative cooldown");village.PotionReadyAt=0;actor.Health.ServerSetVitals(100,10);Check(village.ServerDrinkPotion(1,out _)&&actor.Health.CurrentHealth>=85,"Major potion heals 75%");Check(!village.ServerDrinkPotion(8,out _),"Unknown potion is rejected");beastIndex=0;step=610;next=EditorApplication.timeSinceStartup+.3;return;}
 if(step==610){if(beastIndex>=5){Check(RiftControls.Find("WorldMap")!=null&&RiftControls.Find("PotionMajor")!=null,"Map and both potion actions are rebindable");step=620;next=EditorApplication.timeSinceStartup+.3;return;}var d=bestiary.Where(d=>!d.IsWildlife).ElementAt(beastIndex);var zone=UnityEngine.Object.FindFirstObjectByType<RiftEnemyPopulation>().Zones.First(z=>z.Encounter&&!z.Encounter.MiniBoss);NavMesh.SamplePosition(zone.SpawnPoints[0].position,out var floor,12,NavMesh.AllAreas);actor.ServerTeleport(floor.position,0);actor.Health.ServerSetVitals(10000,10000);var pos=floor.position+Vector3.forward*1.2f;NavMesh.SamplePosition(pos,out var enemyFloor,3,NavMesh.AllAreas);beast=UnityEngine.Object.Instantiate(d.Prefab,enemyFloor.position,Quaternion.identity);NetworkServer.Spawn(beast.gameObject);beast.enabled=false;beastBefore=actor.Health.CurrentHealth;Check(beast.ServerTrySkill(actor.Health),"Authoritative ability starts: "+d.SkillName);Advance(1.8);return;}
 if(step==611){typeof(RiftEnemyAgent).GetMethod("TickSkill",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(beast,new object[]{NetworkTime.time});Advance(.8);return;}
 if(step==612){Check(actor.Health.CurrentHealth<beastBefore,"Ability deals server damage: "+beast.Definition.DisplayName);beast.Despawn();beastIndex++;step=610;next=EditorApplication.timeSinceStartup+.3;return;}
 if(step==620){var position=actor.transform.position;foreach(var d in bestiary.Where(d=>d.IsWildlife)){NavMesh.SamplePosition(position+UnityEngine.Random.insideUnitSphere*3,out var floor,6,NavMesh.AllAreas);var animal=UnityEngine.Object.Instantiate(d.Prefab,floor.position,Quaternion.identity);NetworkServer.Spawn(animal.gameObject);animals.Add(animal);Check(animal.GetComponent<NavMeshAgent>().isOnNavMesh&&NetworkServer.spawned.ContainsKey(animal.netId),"Wildlife spawns on native navigation/network: "+d.DisplayName);}Advance(2);return;}
 if(step==621){Check(animals.Where(a=>a.Definition.Disposition!=RiftEnemyDisposition.Hostile).All(a=>!a.Target),"Defensive and timid fauna do not initiate combat");Check(animals.Any(a=>a.Definition.Disposition==RiftEnemyDisposition.Hostile&&a.Target==actor.Health),"Rift wolf acquires player as a hostile target");Check(animals.Where(a=>a.Definition.Disposition==RiftEnemyDisposition.Timid).Any(a=>(a.transform.position-a.Home).sqrMagnitude>.1f),"Timid fauna moves away from the player");foreach(var animal in animals)animal.Despawn();Capture("potions");RiftControls.Bind("WorldMap",0,"<Keyboard>/f9");Press(UnityEngine.InputSystem.Key.F9);Advance(.5);return;}
 if(step==622){Check(field.MapOpen,"Rebound map action opens with F9");Press();field.SetMap(false);RiftControls.Bind("Potion",0,"<Keyboard>/f7");player.GetComponent<RiftVillagePlayer>().PotionReadyAt=0;actor.Health.ServerSetVitals(170,10);PlayerPrefs.SetInt(RiftVillageSupplies.Key(0),3);Press(UnityEngine.InputSystem.Key.F7);Advance(.5);return;}
 if(step==623){Check(RiftVillageSupplies.Count(0)==2,"Rebound potion action consumes from F7");Press();Finish(true);return;}

 }
}}

